// Replace the FIVE non-secret placeholders in this node after import.
// Bind TWO separate n8n Header Auth credentials to the EspoCRM / Chatwoot GET nodes.
// This diagnostic workflow NEVER sends messages or edits existing systems.
const config={
  espoUrl:'https://REPLACE_ESPO_HOST',
  espoCampaignId:'REPLACE_ESPO_CAMPAIGN_ID',
  chatwootUrl:'https://REPLACE_CHATWOOT_HOST',
  chatwootAccountId:'REPLACE_CHATWOOT_ACCOUNT_ID',
  chatwootCampaignId:'REPLACE_CHATWOOT_CAMPAIGN_ID',
};
if(Object.values(config).some(v=>!v || v.includes('REPLACE_'))) throw new Error('READ_ONLY_SETUP_REQUIRED: configure non-secret host/IDs; bind existing API Header Auth credentials');
for(const u of [config.espoUrl,config.chatwootUrl]) {
 const parsed=new URL(u);
 if(parsed.protocol!=='https:') throw new Error('HTTPS required');
}
return [{json:config}];

// Summarize availability without copying full CRM campaign/recipient records into the result.
const campaign=$('GET Espo Campaign - Read Only').first().json;
const summary=$('GET Espo Campaign Summary - Read Only').first().json;
const chatwoot=$('GET Chatwoot Campaign - Read Only').first().json;
const metrics=$('GET Chatwoot Analytics Metrics - Read Only').first().json;
if(!campaign || !summary || !chatwoot || !metrics || typeof metrics!=='object') throw new Error('Incomplete read-only probe');
return [{json:{
    checkedAt:new Date().toISOString(),
    mode:'READ_ONLY',
    liveSendAttempted:false,
    espoCampaignReadable:!!campaign.id,
    espoSummaryReadable:true,
    chatwootCampaignReadable:true,
    chatwootMetricsReadable:true,
    chatwootCampaignStatus:chatwoot.campaign_status ?? null,
    chatwootAudienceCount:Number.isInteger(metrics.audience)?metrics.audience:null,
    chatwootDeliveredCount:Number.isInteger(metrics.delivered)?metrics.delivered:null,
    metaMessageIdAvailable:false,
    crmRecipientEventSyncEnabled:false
}}];
